// ================= SETTINGS (fill these in) =================
const STEAM_API_KEY = '***REDACTED***';
const STEAM_ID = '76561198347493742';     // 17 digits, starts with 7656...
const NTFY_TOPIC = 'Trophies-abdomario-x0007';  // e.g. trophies-ahmad-x7k29q
// For testing only: set to e.g. 72 to get alerts for unlocks from the
// last 72 hours. Set back to 0 before turning the workflow on.
const TEST_LOOKBACK_HOURS = 0;
// =============================================================

const state = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);

// First real run: remember "now" so you don't get spammed with old unlocks.
let since = state.lastCheck ?? now;
if (TEST_LOOKBACK_HOURS > 0) since = now - TEST_LOOKBACK_HOURS * 3600;

const api = 'https://api.steampowered.com';
const get = (path, qs) =>
  this.helpers.httpRequest({ method: 'GET', url: api + path, qs, json: true });

// 1) Games you played in the last 2 weeks
const recent = await get('/IPlayerService/GetRecentlyPlayedGames/v1/', {
  key: STEAM_API_KEY, steamid: STEAM_ID, count: 10,
});
const games = recent?.response?.games ?? [];

const sent = [];

for (const game of games) {
  // 2) Your achievements for this game
  let list;
  try {
    const res = await get('/ISteamUserStats/GetPlayerAchievements/v1/', {
      key: STEAM_API_KEY, steamid: STEAM_ID, appid: game.appid, l: 'english',
    });
    list = res?.playerstats?.achievements;
  } catch (e) {
    continue; // game has no achievements, or profile game details are private
  }
  if (!list || list.length === 0) continue;

  const newOnes = list
    .filter(a => a.achieved === 1 && a.unlocktime > since)
    .sort((a, b) => a.unlocktime - b.unlocktime);
  if (newOnes.length === 0) continue;

  // 3) Icons for the achievements (only fetched when something is new)
  const icons = {};
  try {
    const schema = await get('/ISteamUserStats/GetSchemaForGame/v2/', {
      key: STEAM_API_KEY, appid: game.appid, l: 'english',
    });
    for (const s of schema?.game?.availableGameStats?.achievements ?? []) {
      icons[s.name] = s.icon;
    }
  } catch (e) { /* icons are optional */ }

  const total = list.length;
  const unlocked = list.filter(a => a.achieved === 1).length;
  const percent = Math.round((unlocked / total) * 100);

  for (const a of newOnes) {
    const msg = {
      topic: NTFY_TOPIC,
      title: `Trophy unlocked: ${game.name}`,
      message: `${a.name || a.apiname}\n${a.description || '(hidden achievement)'}\nProgress: ${unlocked}/${total} (${percent}%)`,
      tags: ['trophy'],
    };
    if (icons[a.apiname]) msg.icon = icons[a.apiname];
    await this.helpers.httpRequest({ method: 'POST', url: 'https://ntfy.sh/', body: msg, json: true });
    sent.push({ game: game.name, achievement: a.name || a.apiname, progress: `${unlocked}/${total}` });
  }

  // 4) Platinum: everything unlocked, and the last one just happened
  if (unlocked === total) {
    await this.helpers.httpRequest({
      method: 'POST', url: 'https://ntfy.sh/', json: true,
      body: {
        topic: NTFY_TOPIC,
        title: `PLATINUM: ${game.name}`,
        message: `All ${total} achievements unlocked!`,
        tags: ['trophy', 'tada'],
        priority: 5,
      },
    });
    sent.push({ game: game.name, achievement: 'PLATINUM', progress: `${total}/${total}` });
  }
}

state.lastCheck = now;

return [{ json: { checkedGames: games.length, since: new Date(since * 1000).toISOString(), notificationsSent: sent.length, sent } }];
